#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001'
test ! -L '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001'
mkdir '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001'
mkdir '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/src' '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/contracts' '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/src/probe_us_input_headers_v1.py'
printf '%s  %s\n' '33f9d81a050b588b4184061e9400a17de7e9fa23163c34324cffb51e5c4847ed' '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/src/probe_us_input_headers_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/contracts/INPUT_HEADER_SCOPE_v1.json'
printf '%s  %s\n' '2cbf8b4f6cc3787a07c9282ec9a84ca008a6b7dff56f6b40c1c3f2aa463f7d11' '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/contracts/INPUT_HEADER_SCOPE_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/input_headers_v1.sbatch'
printf '%s  %s\n' '70884b89061d1d56817ac29987605fd53e0c5b97310a3396711e2ea53f92c29c' '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/input_headers_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/input_headers_v1.sbatch')
case "$job" in ''|*[!0-9]*) exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/us_input_header_padding_v2_20261007_001/job_id.txt'
printf 'INPUT_HEADER_ROOT=/data1/home/sunyiq/us_input_header_padding_v2_20261007_001\nINPUT_HEADER_JOB_ID=%s\nINPUT_HEADER_SUBMITTED_ONCE\n' "$job"
